// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, address ref) public {
        vm.assume(user != address(0));
        // Seed the market to initialize
        c.seedMarket{value: 1}(100);

        // Give user some kilos so getMyDrugs() returns a nonzero value
        c.getFreeKilo();

        // Record block timestamp before collectDrugs
        uint256 timestampBefore = block.timestamp;

        // Call collectDrugs as user
        vm.prank(user);
        c.collectDrugs(ref);

        // Assert that lastCollect[user] was updated to block.timestamp
        assertTrue(c.lastCollect(user) == timestampBefore);
    }
}

